package com.pp.shaderlod.optimization.blisswater.mixin;import com.llamalad7.mixinextras.injector.ModifyReturnValue;import com.llamalad7.mixinextras.sugar.Local;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.At;import net.caffeinemc.mods.sodium.client.gl.shader.GlProgram;import net.irisshaders.iris.pipeline.IrisRenderingPipeline;import net.irisshaders.iris.shaderpack.programs.ProgramSource;import com.pp.shaderlod.optimization.blisswater.BlissWaterShadowRuntime;@Mixin(targets="net.irisshaders.iris.pipeline.programs.SodiumPrograms",remap=false)public abstract class ShadowLegacyOwnerMixin{@ModifyReturnValue(method="createShader",at=@At("RETURN"),require=1)private GlProgram<?> own(GlProgram<?> p,@Local(argsOnly=true) IrisRenderingPipeline owner,@Local(argsOnly=true) ProgramSource source){if(p!=null&&source!=null&&source.getParent()!=null)BlissWaterShadowRuntime.own(owner,source.getParent().getPack(),source.getName(),p.handle());return p;}}
